package com.gameaggregator.releaseservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.releaseservice.api.ReleaseDtos.*;import com.gameaggregator.releaseservice.domain.*;import com.gameaggregator.releaseservice.infrastructure.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class ReleaseService{final ReleaseRepository releases;final ReleaseDecisionRepository decisions;public ReleaseService(ReleaseRepository r,ReleaseDecisionRepository d){releases=r;decisions=d;}public Release create(Create r){return releases.save(new Release(r.gameId(),r.versionId(),r.buildId(),r.channel(),r.releaseNotes(),r.createdBy()));}public List<Release> list(UUID gameId){return gameId==null?releases.findAll():releases.findAllByGameId(gameId);}public Release get(UUID id){return releases.findById(id).orElseThrow(()->new NotFoundException("RELEASE_NOT_FOUND","Release was not found"));}public Release notes(UUID id,Notes r){var x=get(id);require(x,"DRAFT");x.releaseNotes=r.releaseNotes();return x;}public Release submit(UUID id){var x=get(id);require(x,"DRAFT");x.status="PENDING_APPROVAL";return x;}public Release approve(UUID id,Decision r){var x=get(id);require(x,"PENDING_APPROVAL");x.status="APPROVED";x.approvedBy=r.actorId();x.approvedAt=Instant.now();decisions.save(new ReleaseDecision(id,r.actorId(),"APPROVED",r.comment()));return x;}public Release reject(UUID id,Decision r){var x=get(id);require(x,"PENDING_APPROVAL");x.status="REJECTED";decisions.save(new ReleaseDecision(id,r.actorId(),"REJECTED",r.comment()));return x;}public Release publish(UUID id,Publish r){var x=get(id);require(x,"APPROVED");x.status="RELEASED";x.releasedAt=Instant.now();return x;}public Release rollback(UUID id,Rollback r){var source=get(id);require(source,"RELEASED");source.status="ROLLED_BACK";var rollback=new Release(source.gameId,source.versionId,source.buildId,source.channel,r.releaseNotes(),r.actorId());rollback.status="RELEASED";rollback.rollbackOfReleaseId=source.id;rollback.releasedAt=Instant.now();return releases.save(rollback);}public List<ReleaseDecision> decisions(UUID id){get(id);return decisions.findAllByReleaseId(id);}private void require(Release r,String s){if(!s.equals(r.status))throw new IllegalStateException("Release must be "+s+" but was "+r.status);}}